    /// <summary>
    /// Find EcoResCategory using this.ProductCategoryName
    /// </summary>
    /// <param name = "_entityCtx">Data entity context</param>
    /// <param name = "_dataSourceCtx">Datasource context</param>
    /// <returns></returns>
    public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        Common ret;

        ret = super(_entityCtx, _dataSourceCtx);

        if (!ret.RecId && _dataSourceCtx.name() == dataEntityDataSourceStr(EcoResProductCategoryAssignmentEntity, EcoResCategory))
        {
            ret = EcoResCategory::findByName(this.ProductCategoryName, EcoResCategoryHierarchyRole::getHierarchiesByRole(EcoResCategoryNamedHierarchyRole::Retail).CategoryHierarchy);
        }

        return ret;
    }

    /// <summary>
    /// Map entity this.ProductCategoryName to ecoResCategory datasource
    /// </summary>
    /// <param name = "_entityCtx">Data entity context</param>
    /// <param name = "_dataSourceCtx">Datasource context</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(METPalletRoundingPolicyLineEntity, EcoResCategory) :
                if (this.ProductCategoryName)
                {
                    EcoResCategory ecoResCategory = EcoResCategory::findByName(this.ProductCategoryName, EcoResCategoryHierarchyRole::getHierarchiesByRole(EcoResCategoryNamedHierarchyRole::Retail).CategoryHierarchy);

                    _dataSourceCtx.setBuffer(ecoResCategory);
                }

                break;
        }

        super(_entityCtx, _dataSourceCtx);

        switch (_dataSourceCtx.name())
        {
            case dataEntityDataSourceStr(METPalletRoundingPolicyLineEntity, METPalletRoundingPolicyLine) :
                if (this.ProductCategoryName)
                {
                    METPalletRoundingPolicyLine palletRoundingPolicyLine = _dataSourceCtx.getBuffer();
                    palletRoundingPolicyLine.fieldState(fieldNum(METPalletRoundingPolicyLine, Category), this.fieldState(fieldNum(METPalletRoundingPolicyLineEntity, ProductCategoryName)));
                }
                break;
        }
    }
